// Commentary render test (pipeline/DESIGN.md 17.5; wave-2-layout.md 7) on
// REAL blocks: the golden src-tauri/tests/golden/mhcc-render.json is
// machine-generated by the Rust core from pipeline/out/mhcc.sqlite through
// open_verified (each case is exactly what get_commentary returns:
// John 3:3 in the 1-8 anchor, John 3:16 in no anchor -> the whole chapter,
// Psalm 23:1). No commentary text is typed here.
//
// For every block the drawn panel must show each stored text node exactly
// (one `.ct` span per node, in document order) and no other characters;
// every reference is a link to its range start; the label lines are gated.
import { describe, expect, it } from "vitest";
import { flushSync, mount, unmount } from "svelte";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import CommentaryView from "../src/components/CommentaryView.svelte";
import CommentaryPanel from "../src/components/CommentaryPanel.svelte";
import { refTarget, scopeLabel, verseParts, type CmtView, type CommentaryResult, type VerseRef } from "../src/lib/commentary";
import type { Book } from "../src/lib/types";
import { MHCC_CREDIT } from "../src/lib/attributions";

const golden: Record<string, CommentaryResult> = JSON.parse(
  readFileSync(resolve(process.cwd(), "src-tauri/tests/golden/mhcc-render.json"), "utf8"),
);
type Ok = Extract<CommentaryResult, { status: "ok" }>;
const ok = (k: string) => golden[k] as Ok;

const book = (ord: number, osis: string, name: string, chapters: number): Book =>
  ({ ord, osis, name, heading: name, main_title: null, abbrevs: [], chapters, verses: [] });
const BOOKS: Book[] = [book(4, "Num", "Numbers", 36), book(19, "Ps", "Psalms", 150), book(43, "John", "John", 21)];

function textNodes(root: Node): Text[] {
  const out: Text[] = [];
  const w = document.createTreeWalker(root, 4 /* NodeFilter.SHOW_TEXT */);
  for (let n = w.nextNode(); n; n = w.nextNode()) out.push(n as Text);
  return out;
}

function draw(r: Ok, onRef: (t: VerseRef) => void = () => {}) {
  document.body.innerHTML = '<div id="t"></div>';
  const target = document.getElementById("t")!;
  const c = mount(CommentaryView, { target, props: { groups: r.groups, verseId: r.verse_id, books: BOOKS, onRef } });
  flushSync();
  return { root: target, done: () => unmount(c) };
}

describe("commentary blocks render exactly as stored (real golden)", () => {
  it("the golden covers an anchor, the whole-chapter fallback and a reference", () => {
    expect(ok("John.3.3").whole_chapter).toBe(false);
    expect(ok("John.3.3").groups.map((g) => [g.first, g.last])).toEqual([[43003001, 43003008]]);
    expect(ok("John.3.16").whole_chapter).toBe(true);
    expect(ok("John.3.16").groups[0].first).toBeNull();
    expect(ok("Ps.23.1").status).toBe("ok");
    const refs = Object.values(golden).flatMap((r) => (r as Ok).groups.flatMap((g) => g.blocks.flatMap((b) => b.nodes)))
      .filter((n) => n.name === "reference");
    expect(refs.length).toBeGreaterThan(0);
  });

  for (const key of Object.keys(golden)) {
    it(`${key}: every text node exactly, nothing else`, () => {
      const r = ok(key);
      const clicks: VerseRef[] = [];
      const { root, done } = draw(r, (t) => clicks.push(t));
      for (const g of r.groups) {
        for (const b of g.blocks) {
          const el = root.querySelector<HTMLElement>(`.cmt-block[data-block="${b.id}"]`)!;
          expect(el, `block ${b.id}`).not.toBeNull();
          const stored = b.nodes.filter((n) => n.text !== null);
          // 1. one .ct span per stored text node, in document order, text exact
          const ct = [...el.querySelectorAll<HTMLElement>(".ct")];
          expect(ct.map((s) => Number(s.dataset.n))).toEqual(stored.map((n) => n.n));
          ct.forEach((s, i) => expect(s.textContent).toBe(stored[i].text));
          // 2. the block's DOM text is the stored text nodes and nothing else
          expect(el.textContent).toBe(stored.map((n) => n.text).join(""));
          // (Svelte may leave empty anchor text nodes; they carry no characters)
          for (const t of textNodes(el)) if (t.data !== "") expect(t.parentElement!.classList.contains("ct")).toBe(true);
          // 3. references: a link to the range start, as written
          for (const n of b.nodes.filter((x) => x.name === "reference")) {
            const btn = el.querySelector<HTMLButtonElement>(`button.cmt-ref[data-n="${n.n}"]`)!;
            expect(btn).not.toBeNull();
            const want = refTarget(n)!;
            btn.click();
            expect(clicks.at(-1)).toEqual(want);
            const a = n.attrs.find((x) => x.name === "osisRef")!;
            expect(want).toEqual(verseParts(a.ref_start!));
          }
        }
      }
      // scope lines are UI text, one per group
      const scopes = [...root.querySelectorAll(".cmt-scope")].map((s) => s.textContent);
      expect(scopes).toEqual(r.groups.map((g) => scopeLabel(g, r.verse_id, BOOKS)));
      done();
    });
  }

  it("scope lines and descending references", () => {
    expect(scopeLabel(ok("John.3.3").groups[0], 43003003, BOOKS)).toBe("On John 3:1–8");
    expect(scopeLabel(ok("John.3.16").groups[0], 43003016, BOOKS)).toBe("On John 3 (the whole chapter)");
    expect(scopeLabel(ok("Ps.23.1").groups[0], 19023001, BOOKS)).toBe("On Psalms 23:1");
    // Exod.13.2-Exod.10.13 (DESIGN.md 17.4): navigates to the start, never expanded
    const n = { n: 2, parent: 0, name: "reference", text: null, attrs: [{ name: "osisRef", value: "Exod.13.2-Exod.10.13", ref_start: 2013002, ref_end: 2010013 }] };
    expect(refTarget(n)).toEqual({ book: 2, chapter: 13, verse: 2 });
  });

  it("no raw HTML anywhere in the commentary components", () => {
    for (const f of ["CommentaryView.svelte", "CommentaryPanel.svelte"]) {
      const src = readFileSync(resolve(process.cwd(), "src/components", f), "utf8");
      expect(src).not.toContain("{@html");
      expect(src).not.toContain("innerHTML");
    }
  });
});

describe("commentary panel", () => {
  function panel(view: CmtView) {
    document.body.innerHTML = '<div id="t"></div>';
    const target = document.getElementById("t")!;
    const c = mount(CommentaryPanel, {
      target,
      props: { view, books: BOOKS, widthPx: 352, minPx: 288, maxPx: 576, onClose() {}, onResize() {}, onReset() {}, onRef() {} },
    });
    flushSync();
    return { root: target, done: () => unmount(c) };
  }

  it("the real labels are owner-approved (W2-LBL): title, author with tradition, and date lines exactly as sent", () => {
    const r = ok("John.3.3");
    expect(r.source.approved).toBe(true);
    expect(r.source.author_line).toBe("Matthew Henry · Presbyterian (English Nonconformist), with Thomas Scott · Anglican");
    expect(r.source.date_line).toBe("Abridgement c. 1838 (Religious Tract Society), from Henry's Exposition (1708–1710)");
    const { root, done } = panel({ kind: "done", result: r });
    expect(root.querySelector(".cmt-title")!.textContent).toBe(r.source.title);
    expect(root.querySelector(".cmt-author")!.textContent).toBe(r.source.author_line);
    expect(root.querySelector(".cmt-date")!.textContent).toBe(r.source.date_line);
    expect(root.querySelector(".cmt-pending")).toBeNull();
    expect(root.querySelector('[data-source="CMT-MHCC-CW20"] p')!.textContent).toBe(MHCC_CREDIT.paragraphs[0]);
    done();
  });

  it("labels not approved (pending fixture): title only, with 'Labels awaiting review'; no author or date line", () => {
    const real = ok("John.3.3");
    const r: Ok = { ...real, source: { title: real.source.title, approved: false, author_line: null, date_line: null } };
    const { root, done } = panel({ kind: "done", result: r });
    expect(root.querySelector(".cmt-title")!.textContent).toBe(r.source.title);
    expect(root.querySelector(".cmt-pending")!.textContent).toBe("Labels awaiting review");
    expect(root.querySelector(".cmt-author")).toBeNull();
    expect(root.querySelector(".cmt-date")).toBeNull();
    expect(root.querySelector(".cmt-fallback")).toBeNull();
    // SOURCES.md CMT-MHCC-CW20 condition 3: the source text stays with the commentary
    expect(root.querySelector('[data-source="CMT-MHCC-CW20"] p')!.textContent).toBe(MHCC_CREDIT.paragraphs[0]);
    done();
  });

  it("approved labels: author and date lines exactly as sent", () => {
    const r: Ok = { ...ok("John.3.3"), source: { title: "T", approved: true, author_line: "A · B", date_line: "c. 1838" } };
    const { root, done } = panel({ kind: "done", result: r });
    expect(root.querySelector(".cmt-author")!.textContent).toBe("A · B");
    expect(root.querySelector(".cmt-date")!.textContent).toBe("c. 1838");
    expect(root.querySelector(".cmt-pending")).toBeNull();
    done();
  });

  it("John 3:16: the whole chapter, clearly labelled", () => {
    const { root, done } = panel({ kind: "done", result: ok("John.3.16") });
    expect(root.querySelector(".cmt-fallback")!.textContent).toContain("John 3:16");
    expect(root.querySelector(".cmt-scope")!.textContent).toBe("On John 3 (the whole chapter)");
    done();
  });

  it("unavailable and empty states", () => {
    let p = panel({ kind: "done", result: { status: "unavailable", reason: "mhcc.sqlite: missing" } });
    expect(p.root.textContent).toContain("This commentary is unavailable");
    expect(p.root.textContent).toContain("The Bible text is not affected.");
    expect(p.root.querySelector(".cmt-source")).toBeNull();
    p.done();
    p = panel({ kind: "empty" });
    expect(p.root.querySelector(".empty")).not.toBeNull();
    p.done();
    const none: Ok = { ...ok("John.3.3"), groups: [] };
    p = panel({ kind: "done", result: none });
    expect(p.root.textContent).toContain(`${none.source.title} has no note on John 3:3.`);
    p.done();
  });
});
